}

.container {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
}

.row {
  display: flex;
  flex-direction: row; /* items side by side */
}

.column {
  display: flex;
  flex-direction: column; /* items stacked vertically */
}

/* Flexbox: one direction at a time */
.flex-container {
  display: flex;
}

/* Grid: rows and columns together */
.grid-container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: auto auto;
}
